```js
export function sweepBricks(ball, bricks) {
  const hits = [];
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  const maxStep = 2 * ball.r; // hmm, or a constant
  const steps = Math.max(1, Math.ceil(dist / maxStep));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const x = px + dx * t;
    const y = py + dy * t;
    const overlap = bricks.filter((b) => b.alive && collidesAt(x, y, ball.r, b));
    if (overlap.length) {
      // first contact: all overlapping bricks at this instant are the hits
      return overlap.map((b) => ({ brick: b, x, y }));
    }
  }
  return [];
}
```

