export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the ball was BEFORE this move: `brickCollision` sweeps from
  // this position to the new one to catch fast moves that would otherwise
  // tunnel through a brick (see #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;

