// --- Rendering (DOM) --------------------------------------------------------

// Main render loop. Brick collision is handled by the pure `brickCollision`
// before drawing; this loop only paints the surviving bricks. (The logic used
// to live inside this draw loop — debt #2, still to be fully extracted.)
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score first (issue #1), drawing only here.
  brickCollision(state);

  for (const brick of state.bricks) {
